from torch import nn
import torch
import numpy as np
import os
from scipy.io import loadmat

class GDDUAL(nn.Module):
    '''
    Full standard learnable dual gradientt descent without weight sharing
    '''
    def __init__(self,mat_dim = 6,input_dim = 2,num_steps:int=10,problem_parameters:dict={}):
        super().__init__()
        # Load the matrices that were generated by matlab
        # set one dtype for consistency
        self.dtypus = problem_parameters['dtype']
        self.N = problem_parameters['N']
        self.m = problem_parameters['m']
        self.n = problem_parameters['n']
        self.n_regios = num_steps
        to_load = 'QP_parameters_SS.mat'
        own_dic = os.path.dirname(os.path.dirname(os.path.realpath(__file__)))
        dpc_parameters = loadmat(os.path.join(own_dic,f'mat_files_{self.N}',to_load))        
        # setup the gradient initialization
        G =  dpc_parameters['G']
        AA = dpc_parameters['Kx']
        BB = dpc_parameters['Ku']
        Hinv = np.linalg.inv(dpc_parameters['H'])
        ghg = G@Hinv@G.T
        E = dpc_parameters['E']
        F = dpc_parameters['F']
        eghf = E+G@Hinv@F
        d = dpc_parameters['d']
        Uz = d[0:Hinv.shape[0],0]
        Lz = d[Hinv.shape[0]:,0]
        a_std = 1/np.max(np.linalg.eigh(ghg).eigenvalues)
        a_in = np.log(np.exp(a_std)-1)
        # setup the learnable parameters
        self.ghg    = nn.ParameterList(nn.Parameter(torch.tensor(ghg,  dtype=self.dtypus),requires_grad = True) for _ in range(num_steps))
        self.eghf   = nn.ParameterList(nn.Parameter(torch.tensor(eghf, dtype=self.dtypus),requires_grad = True) for _ in range(num_steps))
        self.d      = nn.ParameterList(nn.Parameter(torch.tensor(d,    dtype=self.dtypus),requires_grad = True) for _ in range(num_steps))
        self.alphas = nn.ParameterList(nn.Parameter(torch.tensor(a_in, dtype=self.dtypus),requires_grad = True) for _ in range(num_steps))
        self.G_imp = nn.Parameter(torch.zeros(eghf.shape, dtype=self.dtypus),requires_grad = True)
        self.h_imp = nn.Parameter(torch.zeros(d.shape[0], dtype=self.dtypus),requires_grad = True)
        # self.lamnull   = nn.Parameter(torch.zeros(d.shape, dtype=self.dtypus),requires_grad = True)
        self.register_buffer('Hinv', torch.tensor(Hinv, dtype = self.dtypus))
        self.register_buffer('F',    torch.tensor(F,    dtype = self.dtypus))
        self.register_buffer('G',    torch.tensor(G,    dtype = self.dtypus))
        self.register_buffer('AA',   torch.tensor(AA,   dtype = self.dtypus))
        self.register_buffer('BB',   torch.tensor(BB,   dtype = self.dtypus))
        self.register_buffer('Lz',   torch.tensor(Lz,   dtype = self.dtypus))
        self.register_buffer('Uz',   torch.tensor(Uz,   dtype = self.dtypus))
        return
    
    def forward(self, xy: torch.Tensor):
        # --------------------------------------------------------------
        # 1. Geräte‑/dtype‑Konsistenz
        # --------------------------------------------------------------
        Hinv = self.Hinv.to(xy)
        F    = self.F.to(xy)
        G    = self.G.to(xy)
        Lz    = self.Lz.to(xy)
        Uz    = self.Uz.to(xy)

        # --------------------------------------------------------------
        # 2. lam0 zum richtigen Shape bringen und broadcasten
        # --------------------------------------------------------------
        batch_size = xy.shape[0]
        lamk = xy @ self.G_imp.T + self.h_imp
        # --------------------------------------------------------------
        # 3. Ergebnisliste – enthält bereits den (broadcasteten) Startwert
        # --------------------------------------------------------------
        lam_list = [lamk]                           # (batch, lam_dim)

        # --------------------------------------------------------------
        # 4. Iterative Dual‑Gradient‑Descent‑Schritte
        # --------------------------------------------------------------
        for i in range(self.n_regios):
            ghg_sym = 0.5 * self.ghg[i] + 0.5 * self.ghg[i].T   # (lam_dim, lam_dim)

            term1 = lamk @ ghg_sym            # (batch, lam_dim)
            term2 = xy @ self.eghf[i].T       # (batch, lam_dim)

            step = torch.nn.functional.softplus(self.alphas[i])
            lamkp1 = torch.nn.functional.relu(lamk - step * (term1 + term2 + self.d[i].T))

            lam_list.append(lamkp1)
            lamk = lamkp1

        # --------------------------------------------------------------
        # 5. Stapeln → (batch, lam_dim, n_steps+1)
        # --------------------------------------------------------------
        lam = torch.stack(lam_list, dim=2)

        # --------------------------------------------------------------
        # 6. Restliche Berechnungen (unverändert)
        # --------------------------------------------------------------
        Fx   = xy @ F.T
        Glam = torch.matmul(G.T, lam)
        rhs  = Fx.unsqueeze(-1) + Glam
        z_pred   = -torch.matmul(Hinv, rhs)
        Lz_b = Lz.view(1, -1, 1)
        Uz_b = Uz.view(1, -1, 1)
        # clamp z_pred into [Lz, Uz]
        z_full = torch.clamp(z_pred, min=-Lz_b, max=Uz_b)
        return z_full, z_full, lam

